function operationReady(id){const o=OPERATIONS[id];return o&&!save.claimedOperations.includes(id)&&o.progress()>=o.target}
function readyOperations(){return Object.keys(OPERATIONS).filter(operationReady)}
function claimOperation(id){if(!operationReady(id))return;const o=OPERATIONS[id];save.claimedOperations.push(id);save.credits+=o.reward;save.stats.operationsClaimed=save.claimedOperations.length;AUDIO.sfx('operation');toast(`OPERATION COMPLETE — ${o.name}`,`+${o.reward} CR`);if(save.claimedOperations.length>=10)unlockAchievement('operations_10');persist(false);renderOperations();renderMenu()}
function renderOperations(){const grid=$('operationsGrid');grid.innerHTML='';for(const [id,o] of Object.entries(OPERATIONS)){const done=save.claimedOperations.includes(id),p=Math.min(o.target,o.progress()),ready=!done&&p>=o.target,d=document.createElement('div');d.className=`operationCard${done?' done':''}${ready?' ready':''}`;d.innerHTML=`<div><div class="name">${done?'◆':ready?'◇':'·'} ${o.name}</div><div class="tiny">${o.desc}</div><div class="opProgress"><span style="width:${Math.min(100,p/o.target*100)}%"></span></div><div class="tiny">${p} / ${o.target} · ${done?'CLAIMED':`${o.reward} CR`}</div></div><button ${ready?'':'disabled'}>${done?'DONE':ready?'CLAIM':'LOCKED'}</button>`;d.querySelector('button').onclick=()=>claimOperation(id);grid.appendChild(d)}$('operationsSummary').textContent=`${save.claimedOperations.length}/${Object.keys(OPERATIONS).length} · ${readyOperations().length} READY`}

