  $('frameStage').style['--frame-accent']=pal.accent;$('frameStage').style['--frame-edge']=pal.edge;
  $('frameName').textContent=s.name;$('frameRole').textContent=s.role;$('frameDescription').textContent=s.summary||s.desc;$('frameDescription').title=s.desc;$('frameMastery').textContent=`MASTERY M${mastery}`;$('frameMastery').style.color=masteryColor(mastery);
