  const frame=SHIPS[state.p.frame],hullPct=Math.round(state.p.hp/state.p.maxHp*100);
  $('pauseSnapshot').innerHTML=`<div><span>RUN TIME</span><b>${fmtTime(state.time)}</b></div><div><span>SHIP HEALTH</span><b>${Math.ceil(state.p.hp)} / ${Math.ceil(state.p.maxHp)} · ${hullPct}%</b></div><div><span>YOUR FRAME</span><b>${frame.name} · LEVEL ${state.level}</b></div><div class="pauseObjective"><span>NEXT OBJECTIVE</span><b>${runObjective()}</b></div>`;
