addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',handleWindowBlur);addEventListener('focus',handleWindowFocus);addEventListener('gamepadconnected',handleGamepadConnected);addEventListener('gamepaddisconnected',handleGamepadDisconnected);document.addEventListener?.('visibilitychange',()=>document.hidden?handleWindowBlur():handleWindowFocus());
