canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const p=pointerToCanvas(e);mouse.inside=true;mouse.x=p.x;mouse.y=p.y;return}if(touch.active){touch.x=e.clientX;touch.y=e.clientY}});
canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse'){if(e.button===0)mouse.active=false}else touch.active=false});canvas.addEventListener('pointercancel',e=>{if(e.pointerType==='mouse')mouse.active=false;else touch.active=false});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
function toggleFullscreen(){document.fullscreenElement?document.exitFullscreen():$('wrap').requestFullscreen?.()}

function pollGamepadPause(){const gps=navigator.getGamepads?.()||[],gp=gps.find(Boolean),pressed=!!(gp&&(gp.buttons[9]?.pressed||gp.buttons[8]?.pressed));if(pressed&&!gamepadPauseLatch&&state?.mode==='run'&&!state.choosing&&!state.archiveOpen&&!state.reliquaryOpen&&!$('settingsScreen').classList.contains('show'))togglePause();gamepadPauseLatch=pressed}
function visibleOverlay(){const overlays=[...(document.querySelectorAll?.('.overlay.show')||[])];return overlays.at(-1)||null}
function gamepadUiButtons(overlay){return overlay?[...overlay.querySelectorAll('button')].filter(b=>!b.disabled&&!b.classList.contains('hidden')&&b.offsetParent!==null):[]}
function focusGamepadDefault(overlay,buttons){if(!buttons.length)return;const preferred=buttons.find(b=>b.classList.contains('primary'))||buttons.find(b=>b.classList.contains('selected'))||buttons[0];preferred.focus?.({preventScroll:true});preferred.scrollIntoView?.({block:'nearest',inline:'nearest'})}
function moveGamepadFocus(buttons,dx,dy){if(!buttons.length)return;let cur=document.activeElement;if(!buttons.includes(cur)){focusGamepadDefault(visibleOverlay(),buttons);return}const r=cur.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let best=null,bestScore=Infinity;for(const b of buttons){if(b===cur)continue;const q=b.getBoundingClientRect(),x=q.left+q.width/2,y=q.top+q.height/2,vx=x-cx,vy=y-cy;if(dx&&Math.sign(vx)!==Math.sign(dx)||dy&&Math.sign(vy)!==Math.sign(dy))continue;const primary=dx?Math.abs(vx):Math.abs(vy),cross=dx?Math.abs(vy):Math.abs(vx),score=primary+cross*2.4;if(primary<3||score>=bestScore)continue;best=b;bestScore=score}if(!best){const i=buttons.indexOf(cur),step=dx<0||dy<0?-1:1;best=buttons[(i+step+buttons.length)%buttons.length]}best.focus?.({preventScroll:true});best.scrollIntoView?.({block:'nearest',inline:'nearest'});AUDIO.sfx('ui')}
function gamepadBack(overlay){if(!overlay)return;const back=overlay.querySelector('[data-close], #confirmCancelBtn, #archiveContinueBtn, #reliquaryClaimBtn:not(.hidden), #reliquarySkipBtn:not(.hidden), #loadoutBackBtn, #settingsBackBtn, #resumeBtn');if(back&&!back.disabled){back.click();back.focus?.({preventScroll:true})}}
function pollGamepadUi(){const gps=navigator.getGamepads?.()||[],gp=gps.find(Boolean),overlay=visibleOverlay();if(!gp||!overlay){gamepadUiOverlay='';gamepadUiMoveLatch=gamepadUiALatch=gamepadUiBLatch=false;return}const buttons=gamepadUiButtons(overlay);if(gamepadUiOverlay!==overlay.id){gamepadUiOverlay=overlay.id;focusGamepadDefault(overlay,buttons)}const ax=gp.axes?.[0]||0,ay=gp.axes?.[1]||0,left=gp.buttons[14]?.pressed||ax<-.62,right=gp.buttons[15]?.pressed||ax>.62,up=gp.buttons[12]?.pressed||ay<-.62,down=gp.buttons[13]?.pressed||ay>.62,moving=left||right||up||down;if(moving&&!gamepadUiMoveLatch)moveGamepadFocus(buttons,(right?1:0)-(left?1:0),(down?1:0)-(up?1:0));gamepadUiMoveLatch=!!moving;const a=!!gp.buttons[0]?.pressed,b=!!gp.buttons[1]?.pressed;if(a&&!gamepadUiALatch){const active=document.activeElement;if(buttons.includes(active)){active.click();AUDIO.sfx('ui')}}if(b&&!gamepadUiBLatch)gamepadBack(overlay);gamepadUiALatch=a;gamepadUiBLatch=b}
function moveInput(){let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);const gps=navigator.getGamepads?.()||[];const gp=gps.find(Boolean);if(gp){const ax=Math.abs(gp.axes[0]||0)>.16?gp.axes[0]:0,ay=Math.abs(gp.axes[1]||0)>.16?gp.axes[1]:0;dx+=ax+(gp.buttons[15]?.pressed?1:0)-(gp.buttons[14]?.pressed?1:0);dy+=ay+(gp.buttons[13]?.pressed?1:0)-(gp.buttons[12]?.pressed?1:0);}if(touch.active){const tx=touch.x-touch.startX,ty=touch.y-touch.startY,l=Math.hypot(tx,ty);if(l>8){dx+=tx/Math.max(45,l);dy+=ty/Math.max(45,l)}}const mouseDriving=save.settings.mouse==='FOLLOW'&&mouse.inside||save.settings.mouse==='HOLD'&&mouse.active;if(mouseDriving&&state?.p){const tx=mouse.x-state.p.x,ty=mouse.y-state.p.y,l=Math.hypot(tx,ty);if(l>10){dx+=tx/l;dy+=ty/l}}return{dx,dy}}

function wrapScreen(value,size){return((value%size)+size)%size}
function translateWorld(dx,dy){
  if(!state||(!dx&&!dy))return false;
  const pointGroups=['enemies','bullets','enemyBullets','orbs','caches','mines','rifts','allies','particles','floaters','deathFx','impactFx'];
  for(const group of pointGroups)for(const item of state[group]||[]){if(Number.isFinite(item.x))item.x+=dx;if(Number.isFinite(item.y))item.y+=dy}
  for(const item of [...(state.arcs||[]),...(state.beams||[])]){if(Number.isFinite(item.x1))item.x1+=dx;if(Number.isFinite(item.y1))item.y1+=dy;if(Number.isFinite(item.x2))item.x2+=dx;if(Number.isFinite(item.y2))item.y2+=dy}
  const p=state.p;p.x+=dx;p.y+=dy;for(const key of ['dashFromX','dashToX','_renderX'])if(Number.isFinite(p[key]))p[key]+=dx;for(const key of ['dashFromY','dashToY','_renderY'])if(Number.isFinite(p[key]))p[key]+=dy;
  state.worldX=(state.worldX||0)-dx;state.worldY=(state.worldY||0)-dy;
  for(const star of state.stars||[]){const parallax=.08+.07/(star.z||1);star.x=wrapScreen(star.x+dx*parallax,W);star.y=wrapScreen(star.y+dy*parallax,H)}
  return true
}
function followWorldCamera(){
  if(!state?.p)return{x:0,y:0};const p=state.p;
  const dx=p.x<CAMERA_SAFE.left?CAMERA_SAFE.left-p.x:p.x>CAMERA_SAFE.right?CAMERA_SAFE.right-p.x:0;
  const dy=p.y<CAMERA_SAFE.top?CAMERA_SAFE.top-p.y:p.y>CAMERA_SAFE.bottom?CAMERA_SAFE.bottom-p.y:0;
  translateWorld(dx,dy);return{x:dx,y:dy}
}
function withinWorldRange(item,padding=260){return item.x>-padding&&item.x<W+padding&&item.y>-padding&&item.y<H+padding}

function cellNoise(x,y,salt=0){let h=Math.imul((x|0)^Math.imul(salt+11,0x45d9f3b),(y|0)^0x27d4eb2d);h=Math.imul(h^(h>>>16),0x45d9f3b);h=Math.imul(h^(h>>>16),0x45d9f3b);return((h^(h>>>16))>>>0)/4294967295}
function worldNodeType(roll){return roll<.23?'repair':roll<.46?'flux':roll<.69?'salvage':roll<.85?'relic':roll<.96?'jammer':'fracture'}
function generateWorldCell(cx,cy){
  const key=`${cx}:${cy}`;if(state.generatedCells.has(key))return;state.generatedCells.add(key);
  const siteKinds=['asteroids','wreck','ion','void'],siteKind=siteKinds[Math.floor(cellNoise(cx,cy,1)*siteKinds.length)],siteWx=(cx+.12+cellNoise(cx,cy,2)*.76)*WORLD_CELL_SIZE,siteWy=(cy+.12+cellNoise(cx,cy,3)*.76)*WORLD_CELL_SIZE;
  state.worldSites.push({key,kind:siteKind,wx:siteWx,wy:siteWy,x:siteWx-state.worldX,y:siteWy-state.worldY,size:46+cellNoise(cx,cy,4)*72,seed:cellNoise(cx,cy,5)});
  if(cx===0&&cy===0||cellNoise(cx,cy,6)<.18)return;
  const wx=(cx+.18+cellNoise(cx,cy,7)*.64)*WORLD_CELL_SIZE,wy=(cy+.18+cellNoise(cx,cy,8)*.64)*WORLD_CELL_SIZE,type=worldNodeType(cellNoise(cx,cy,9)),meta=WORLD_NODE_TYPES[type];
  state.worldNodes.push({id:`${key}:${type}`,type,wx,wy,x:wx-state.worldX,y:wy-state.worldY,r:type==='jammer'?18:type==='fracture'?19:15,color:meta.color,disposition:meta.disposition,collected:false,active:false,pulse:cellNoise(cx,cy,10)*Math.PI*2});
}
function collectWorldNode(node){
  if(node.collected)return false;node.collected=true;state.explorationFinds++;save.stats.fieldSignals++;const meta=WORLD_NODE_TYPES[node.type],p=state.p;let detail='';
  if(node.type==='repair'){const before=p.hp,heal=p.maxHp*.18*(state.contract?.heal??1);p.hp=Math.min(p.maxHp,p.hp+heal);const restored=Math.round(p.hp-before);if(restored<1)runCredit(6);state.enemyBullets=state.enemyBullets.filter(b=>dist2(b,p)>115*115);detail=restored>0?`RESTORED ${restored} HULL · CLEARED NEARBY SHOTS`:'HULL FULL · GAINED 6 CREDITS'}
  else if(node.type==='flux'){state.fieldBoostUntil=Math.max(state.fieldBoostUntil,state.time+18);p.dashCooldown=0;state.score+=180*state.diff.score;detail='+25% ALL WEAPON DAMAGE FOR 18 SEC · DASH READY'}
  else if(node.type==='salvage'){runCredit(12);gainXp(6);state.score+=120*state.diff.score;detail='GAINED 12 CREDITS · GAINED 6 XP'}
  else if(node.type==='fracture'){state.timeFractureRemaining=Math.max(state.timeFractureRemaining||0,9);state.fractureKills=0;state.timeFractures++;save.stats.timeFractures++;state.score+=480*state.diff.score;p.iFrames=Math.max(p.iFrames,.35);detail='WORLD + MUSIC AT 28% SPEED · YOU REMAIN FULL SPEED · 9 SEC';AUDIO.sfx('timeFracture');rewardCue('TIME FRACTURE','WORLD AND MUSIC SLOWED · YOUR SHIP STAYS FAST',3,2100);persist(false)}
  else if(node.type==='relic'){runCredit(24);state.fieldBoostUntil=Math.max(state.fieldBoostUntil,state.time+22);if(p.iFrames<=0)hitPlayer(p.maxHp*.08);if(!state.gameOver)for(let i=0;i<5;i++)spawnEnemy(i===0&&state.time>70?'tank':'scout',false);detail='GAINED 24 CREDITS · +25% DAMAGE FOR 22 SEC · 5 HOSTILES SPAWNED'}
  else{save.stats.hazardsTriggered++;state.hazardFinds++;state.interferenceUntil=Math.max(state.interferenceUntil,state.time+14);p.dashCooldown=Math.max(p.dashCooldown,1.8);if(p.iFrames<=0)hitPlayer(p.maxHp*.06);if(!state.gameOver)for(let i=0;i<4;i++)spawnEnemy(i%2?'charger':'scout',false);detail='SHIP SPEED -28% FOR 14 SEC · 4 HOSTILES SPAWNED'}
  if(node.type!=='fracture')AUDIO.sfx(node.type==='repair'||node.type==='salvage'?'pickup':node.type==='flux'?'overdrive':node.type==='relic'?'paradox':'danger');addShake(node.disposition==='hazard'?7:node.disposition==='risk'?5:node.disposition==='rare'?6:3);particle(node.x,node.y,node.color,node.disposition==='hazard'?22:node.disposition==='rare'?30:14);state.arcs.push({circle:true,x1:node.x,y1:node.y,r:node.disposition==='hazard'?72:node.disposition==='rare'?76:48,life:.22,color:node.color});toast(meta.name,detail);message(`${meta.name}\n${detail}`,node.type==='fracture'?1500:1200);return true
}
function openArchiveFragment(fragment,isNew,detail){if(!state||state.gameOver||!fragment)return false;state.archiveOpen=true;state.paused=true;$('archiveStatus').textContent=isNew?'RECOVERED VOICE':'MEMORY REPLAY';$('archiveChannel').textContent=fragment.channel;$('archiveQuote').textContent=fragment.text;$('archiveNote').textContent=fragment.note;$('archiveReward').textContent=detail;$('archiveProgress').textContent=`PRESERVED ${save.discoveredArchives.length} / ${ARCHIVE_FRAGMENTS.length}`;show('archiveScreen');$('archiveContinueBtn').focus?.({preventScroll:true});return true}
function closeArchiveFragment(){if(!state?.archiveOpen)return false;hide('archiveScreen');state.archiveOpen=false;state.paused=false;state.last=performance.now();const xp=state.archiveXpPending||0;state.archiveXpPending=0;AUDIO.releaseFocus();AUDIO.sfx('resume');if(xp)gainXp(xp);return true}
$('archiveContinueBtn').onclick=closeArchiveFragment;
function updateWorldGeneration(){
  if(!state?.p)return;const pwx=state.worldX+state.p.x,pwy=state.worldY+state.p.y,cx=Math.floor(pwx/WORLD_CELL_SIZE),cy=Math.floor(pwy/WORLD_CELL_SIZE);
  for(let x=cx-WORLD_GENERATION_RADIUS;x<=cx+WORLD_GENERATION_RADIUS;x++)for(let y=cy-WORLD_GENERATION_RADIUS;y<=cy+WORLD_GENERATION_RADIUS;y++)generateWorldCell(x,y);
  for(const site of state.worldSites){site.x=site.wx-state.worldX;site.y=site.wy-state.worldY;site.active=withinWorldRange(site,site.size+120)}
  for(const node of state.worldNodes){node.x=node.wx-state.worldX;node.y=node.wy-state.worldY;node.active=!node.collected&&withinWorldRange(node,460);const contact=node.r+state.p.r+5,safeSignal=node.disposition==='boon'||node.disposition==='rare',pickupRadius=safeSignal?Math.max(contact,state.p.magnet*.82+node.r):contact;if(node.active&&dist2(node,state.p)<pickupRadius*pickupRadius)collectWorldNode(node)}
}
const SIGNAL_FILTERS=['ALL','SUPPORT','TIME','RISK'];
function signalMatchesFilter(node,filter=state?.signalFilter||'ALL'){if(filter==='ALL')return true;if(filter==='SUPPORT')return['repair','flux','salvage'].includes(node.type);if(filter==='TIME')return node.type==='fracture';return node.type==='relic'||node.type==='jammer'}
function nearestWorldNode(filter=state?.signalFilter||'ALL'){let nearest=null,best=Infinity;for(const node of state?.worldNodes||[]){if(node.collected||!signalMatchesFilter(node,filter))continue;const d=dist2(node,state.p);if(d<best){best=d;nearest=node}}return nearest?{node:nearest,distance:Math.sqrt(best)}:null}
function navigationDirection(node){const a=Math.atan2(node.y-state.p.y,node.x-state.p.x),i=Math.round(a/(Math.PI/4)),dirs=['E','SE','S','SW','W','NW','N','NE'];return dirs[(i+8)%8]}
function updateNavigationHud(){const target=nearestWorldNode();navigationSignalLabel.textContent=`FIELD SCANNER · ${state.signalFilter} · N CHANGES FILTER`;if(!target||target.distance>1350){navigationSignal.classList.add('hidden');return}const meta=WORLD_NODE_TYPES[target.node.type];navigationSignal.classList.remove('hidden');navigationSignal.dataset.disposition=meta.disposition;navigationSignalText.textContent=`${meta.name} · ${Math.round(target.distance)}m ${navigationDirection(target.node)}`;navigationSignalEffect.textContent=`${meta.tag} · ${meta.effect}`}
function cycleSignalFilter(){if(!state||state.mode!=='run')return false;const i=Math.max(0,SIGNAL_FILTERS.indexOf(state.signalFilter));state.signalFilter=SIGNAL_FILTERS[(i+1)%SIGNAL_FILTERS.length];updateNavigationHud();AUDIO.sfx('ui');const target=nearestWorldNode(),inRange=target&&target.distance<=1350;toast(`SCANNER FILTER · ${state.signalFilter}`,inRange?`${WORLD_NODE_TYPES[target.node.type].name} · ${Math.round(target.distance)}m`:`No ${state.signalFilter.toLowerCase()} pickup within scanner range.`);return true}
function priorityTarget(){if(!state)return null;return state.enemies.find(e=>e.boss&&!e.dead)||state.enemies.find(e=>e.nemesis&&!e.dead)||state.bounty?.enemy||null}
function updatePriorityHud(){const target=priorityTarget();if(!target||target.dead){prioritySignal.classList.add('hidden');return}const inView=target.x>30&&target.x<W-30&&target.y>78&&target.y<H-45;if(inView){prioritySignal.classList.add('hidden');return}const dx=target.x-state.p.x,dy=target.y-state.p.y,distance=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)+Math.PI/2,label=target.boss?target.bossName:target.nemesis?target.nemesisName:'SIGNAL TARGET';prioritySignal.classList.remove('hidden');prioritySignal.dataset.tone=target.bounty?'bounty':target.boss?'boss':'nemesis';prioritySignalArrow.style.transform=`rotate(${angle}rad)`;prioritySignalText.textContent=`${label} · ${navigationDirection(target)} · ${Math.round(distance)}m`}

function tryPhaseDash(){
  if(!state||state.mode!=='run'||state.paused||state.choosing||state.ceremony||state.gameOver)return false;
  const p=state.p;if((p.dashCooldown||0)>0)return false;let {dx,dy}=moveInput();
  if(Math.hypot(dx,dy)<.12){dx=p._lastMoveX||0;dy=p._lastMoveY||-1}const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;
  p.dashFromX=p.x;p.dashFromY=p.y;p._lastMoveX=dx;p._lastMoveY=dy;p.x+=dx*82;p.y+=dy*82;state.distanceTraveled=(state.distanceTraveled||0)+82;p.dashToX=p.x;p.dashToY=p.y;followWorldCamera();p.dashCooldown=3.1;p.dashFx=.32;p.iFrames=Math.max(p.iFrames,.34);
  let phased=0;for(const b of state.enemyBullets){if(b.life>0&&dist2(b,p)<52*52){b.life=0;phased++}}
  if(phased){state.score+=phased*7*(state.p.scoreMul||1);state.chainTimer=Math.max(state.chainTimer,.8)}
  state.arcs.push({circle:true,x1:p.dashFromX,y1:p.dashFromY,r:24,life:.14,color:'#8de9ff'},{circle:true,x1:p.x,y1:p.y,r:34,life:.18,color:'#8dffd6'});particle(p.dashFromX,p.dashFromY,'#8de9ff',16);particle(p.x,p.y,'#ffffff',12);AUDIO.sfx('dash');addShake(3.5);return true
}

// ---------- RUN HELPERS ----------
function particle(x,y,color='#b7f7ff',n=5){if(!state||save.settings.particles==='OFF'||state.particles.length>=MAX_PARTICLES)return;const mul=save.settings.particles==='LOW'?.45:1;n=Math.max(1,Math.ceil(n*mul));for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=30+Math.random()*90;state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.22+Math.random()*.38,color})}}
function damageNumber(x,y,amount,crit=false){if(!state)return;const mode=save.settings.damageNumbers||'CRITS';if(mode==='OFF'||mode==='CRITS'&&!crit)return;if(state.floaters.length>=90)state.floaters.shift();state.floaters.push({x:x+(Math.random()-.5)*8,y:y-8,text:String(Math.max(1,Math.round(amount))),life:crit?.78:.52,maxLife:crit?.78:.52,crit,color:crit?'#fff2a8':'#bdefff'})}
function addShake(n){if(save.settings.shake!=='ON'||!state)return;const amount=save.settings.motion==='REDUCED'?n*.28:n;state.shake=Math.max(state.shake,amount);if(amount>=5&&phaserScene?.cameras?.main)phaserScene.cameras.main.shake(70+amount*5,Math.min(.008,amount*.00055),true)}
function flashWrap(){if(save.settings.flash==='ON'){const w=$('wrap');w.classList.remove('flash');void w.offsetWidth;w.classList.add('flash');setTimeout(()=>w.classList.remove('flash'),450)}}
function nearest(from,filter=()=>true){let best=null,bestScore=Infinity;const playerTargeting=from===state.p,mode=playerTargeting?(save.settings.targetPriority||'NEAREST'):'NEAREST';for(const e of state.enemies){if(e.dead||!filter(e))continue;const d=dist2(from,e),ratio=e.hp/Math.max(1,e.maxHp),priority=mode==='LOW HULL'?ratio*1e7+d:mode==='ELITES FIRST'?(e.boss||e.nemesis||e.bounty?-2e7:e.elite?-1e7:0)+d:d;if(priority<bestScore){bestScore=priority;best=e}}return best}
function critDamage(base){return base}
function criticalRoll(base){const redline=state.p.hp/state.p.maxHp<=.30?.08:0,drive=(state.driveTier||0)*.018,reckon=state.p.deadReckoning&&state.p.hp/state.p.maxHp<=.25?.10:0,chance=Math.min(.72,state.p.crit+redline+drive+reckon),crit=Math.random()<chance,mult=1.85+(state.p.critDamageBonus||0);return{damage:crit?base*mult:base,crit}}
function critFeedback(e,weaponId,damage){if(!state||state.critFxCooldown>0)return;state.critFxCooldown=.055;AUDIO.sfx('crit',damage,e);state.hitStop=Math.max(state.hitStop,.022);addShake(1.8);particle(e.x,e.y,'#ffffff',5);state.arcs.push({circle:true,x1:e.x,y1:e.y,r:Math.min(24,10+damage*.035),life:.065,color:'#ffffff'});if(weaponId==='rail'&&state.synergies.lanceOptics){const t=nearest(e,x=>x!==e&&dist2(e,x)<170*170);if(t)damageEnemy(t,damage*.30,false,'rail-link',false)}}
function applyResearchToPlayer(p){for(const [id,r] of Object.entries(RESEARCH)){const l=save.research[id]||0;if(l&&r.apply)r.apply(p,l)}p.maxHp=p.baseHp;p.hp=p.maxHp;p.speed=p.baseSpeed;p.damageMul=p.baseDamageMul;p.cooldownMul=p.baseCooldownMul;p.crit=p.baseCrit;p.baseMagnet=p.magnet}
function runCredit(amount){const research=1+(save.research.salvage||0)*.04;state.runCredits+=Math.max(1,Math.round(amount*state.p.creditMul*research*state.diff.credits*(state.contract?.credits||1)*(state.sector?.credits||1)))}
function xpGain(amount){return amount*(1+(save.research.learning||0)*.03)}
function processPendingLevel(){if(!state||state.gameOver||state.choosing||state.ceremony||state.archiveOpen||state.reliquaryOpen||state.xp<state.xpNeed)return false;gainXp(0);return state.choosing}
function recordUpgrade(name,kind,detail){if(!state?.upgradeHistory)return false;state.upgradeHistory.push({name,kind,detail,time:state.time});if(state.upgradeHistory.length>24)state.upgradeHistory.shift();return true}
function enqueueCeremony(title,subtitle,duration=500,onComplete=()=>{},kind='cache'){if(!state||state.gameOver){onComplete();return}const item={title,subtitle,duration,onComplete,kind};state.ceremonyQueue.push(item);processCeremony()}
function processCeremony(){if(!state||state.gameOver||state.ceremony||state.choosing||!state.ceremonyQueue.length)return;const run=state,item=state.ceremonyQueue.shift();if(TEST_MODE){item.onComplete();processCeremony();if(!run.ceremony&&!run.ceremonyQueue.length)processPendingLevel();return}state.ceremony=true;state.paused=true;message(`${item.title}${item.subtitle?`\n${item.subtitle}`:''}`,item.duration+250);if(item.kind==='cache'){AUDIO.sfx('cacheTick',0);setTimeout(()=>AUDIO.sfx('cacheTick',1),Math.max(80,item.duration*.28));setTimeout(()=>AUDIO.sfx('cacheTick',2),Math.max(140,item.duration*.58))}setTimeout(()=>{if(state!==run||run.gameOver)return;item.onComplete();run.ceremony=false;run.paused=false;run.last=performance.now();processCeremony();if(!run.ceremony&&!run.ceremonyQueue.length)processPendingLevel()},item.duration)}
function discoverArtifact(id){if(!save.discoveredArtifacts.includes(id)){save.discoveredArtifacts.push(id);persist(false)}}
function checkSynergies(){if(!state)return[];const unlocked=[];for(const [id,m] of Object.entries(SYNERGIES)){if(state.synergies[id]||!m.condition())continue;state.synergies[id]=true;unlocked.push(m.name);if(!save.discoveredSynergies.includes(id)){save.discoveredSynergies.push(id);persist(false)}AUDIO.sfx('synergy');state.newUnlocks.push(`${m.name} synergy`)}if(unlocked.length)rewardCue('RESONANCE LINK',unlocked.join(' · '),2,1900);checkMetaAchievements();return unlocked}
