const PASSIVE_SCOPE={reactor:'ALL WEAPON DAMAGE',overclock:'ALL WEAPON RATE',targeting:'ALL CRITICAL HITS',armor:'HULL + DAMAGE TAKEN',velocity:'ALL PROJECTILES',thruster:'MOVEMENT',magnet:'ALL PICKUPS',iff:'BOUND ORGANISMS',amplifier:'ALL AREA EFFECTS',capacitor:'SPECIAL SYSTEMS',loyalty:'BOUND ORGANISMS',uplink:'BOUND ORGANISMS',scuttle:'BOUND ORGANISMS'};
function projectedRequirement(req,o){let level=req.type==='weapon'?(state.weapons[req.id]?.level||0):(state.passives[req.id]||0);if(req.type==='weapon'&&o.systemId===req.id){if(o.key.startsWith('new:'))level=Math.max(level,1);else if(o.key.startsWith('w:'))level++}if(req.type==='passive'&&o.passiveId===req.id&&o.key.startsWith('p:'))level++;return level}
