function buildOffers(count=3,excluded=[]){return weighted(buildOfferPool().filter(o=>!excluded.includes(o.key)),count)}
function drawFreshOffers(previousKeys=[],pinnedOffer=null,forcedOffer=null){
  const pinnedKey=pinnedOffer?.key||'',previousUnpinned=previousKeys.filter(key=>key!==pinnedKey),count=pinnedOffer?2:3,excluded=pinnedKey?[pinnedKey]:[],previousSignature=[...previousUnpinned].sort().join('|');
  let offers=buildOffers(count,excluded),attempts=0;
  while(previousSignature&&[...offers.map(o=>o.key)].sort().join('|')===previousSignature&&attempts++<8)offers=buildOffers(count,excluded);
  if(previousSignature&&[...offers.map(o=>o.key)].sort().join('|')===previousSignature){const fresh=buildOfferPool().filter(o=>o.key!==pinnedKey&&!previousUnpinned.includes(o.key));if(fresh.length)offers[offers.length-1]=weighted(fresh,1)[0]}
  if(pinnedOffer){const index=Math.max(0,Math.min(previousKeys.indexOf(pinnedKey),offers.length));offers.splice(index,0,pinnedOffer)}
  if(forcedOffer){const existing=offers.findIndex(o=>o.key===forcedOffer.key);if(existing>=0)offers[existing]=forcedOffer;else{const replace=Math.max(0,offers.findIndex(o=>o.key!==pinnedKey));offers[replace]=forcedOffer}}
  return offers
}
const SIGNAL_DRAW_TIERS={FRESH:{tier:1,detail:'THREE NEW OFFERS'},TUNED:{tier:2,detail:'ONE BUILD-MATCHED OFFER GUARANTEED'},RESONANT:{tier:3,detail:'PRIORITY OFFER · SELECT IT FOR +25% DAMAGE / 20 SEC'}};
