function weaponBeam(w,dt){w.timer-=dt;if(w.timer>0)return;const target=nearest(state.p);if(!target)return;const l=w.level,e=w.evolved,n=(l>=5?2:1)+(e?1:0)+state.p.extraProjectiles,range=500,dmg=38*(1+(l-1)*.20)*(e?1.42:1)*state.p.damageMul*weaponPower('beam',w);w.timer=.92*(l>=4?.84:1)*(e?.70:1)*state.p.cooldownMul/(state.p.specialMul||1);AUDIO.sfx('beam');const base=Math.atan2(target.y-state.p.y,target.x-state.p.x),color=e?'#ffffff':'#35efff';for(let q=0;q<n;q++){const a=base+(q-(n-1)/2)*.11,ex=state.p.x+Math.cos(a)*range,ey=state.p.y+Math.sin(a)*range;emitWeaponFx(state.p.x+Math.cos(a)*11,state.p.y+Math.sin(a)*11,a,'beam',color);state.beams.push({x1:state.p.x,y1:state.p.y,x2:ex,y2:ey,life:.1,color,weaponId:'beam'});const hits=[];for(const x of state.enemies){if(x.dead)continue;const vx=x.x-state.p.x,vy=x.y-state.p.y,along=vx*Math.cos(a)+vy*Math.sin(a),perp=Math.abs(-vx*Math.sin(a)+vy*Math.cos(a));if(along>0&&along<range&&perp<x.r+6)hits.push({e:x,d:along})}hits.sort((A,B)=>A.d-B.d);const cap=2+(l>=2?1:0)+(e?3:0);for(const h of hits.slice(0,cap)){damageEnemy(h.e,critDamage(dmg),false,'beam');emitImpactFx(h.e.x,h.e.y,Math.cos(a),Math.sin(a),'beam',color,h.e.dead);if(state.synergies.prismNet){const t=nearest(h.e,x=>x!==h.e&&dist2(h.e,x)<120*120);if(t){state.arcs.push({x1:h.e.x,y1:h.e.y,x2:t.x,y2:t.y,life:.09,color:'#35efff'});damageEnemy(t,dmg*.32,false,'prism-net',false)}}}}}
