  const telemetry=[metric(state.chainBest,'BEST CHAIN'),metric(state.rushActivations,'SIGNAL RUSHES'),metric(state.rushBest,'BEST RUSH KILLS'),metric(state.grazeBest,'GRAZE STREAK'),metric(numberText(state.damageDealt),'DAMAGE'),metric(numberText(state.damageTaken),'DAMAGE TAKEN'),metric(state.flawlessBosses,'FLAWLESS BOSSES'),metric(state.evolutions,'EVOLUTIONS'),metric(Object.keys(state.synergies).length,'SYNERGIES'),metric(artifact?ARTIFACTS[artifact].name:'NONE','ARTIFACT'),metric(`M${masteryAfter}`,'FRAME MASTERY'),metric(state.cachesOpened,'CACHES'),metric(state.explorationFinds,'FIELD SIGNALS'),metric(state.directiveComplete?'COMPLETE':'INCOMPLETE','FIELD DIRECTIVE'),metric(state.timeFractures,'TIME FRACTURES'),metric(`${(state.distanceTraveled/1000).toFixed(1)} km`,'TRAVEL'),metric(state.ascension||0,'ASCENSION'),metric(Object.keys(state.doctrines).length,'DOCTRINES'),metric(state.nemesisKilled,'ECHO HUNTERS')].join('');
