  $('runUnlocks').innerHTML=state.newUnlocks.map(x=>`<div class="unlockItem">${x}</div>`).join('');const canRevive=!state.revived&&!victory&&!aborted&&save.credits>=120;$('reviveBtn').disabled=!canRevive;$('reviveBtn').textContent='RESTORE FRAME · 120 CR · 30% HULL';$('reviveBtn').title=canRevive?'Spend 120 profile credits. One restore per run.':state.revived?'Restore already used this run.':victory||aborted?'Restore is unavailable after this result.':`Requires 120 profile credits · ${save.credits} available.`;$('gameOverHelp').textContent=canRevive?'RESTORE continues this run with 30% hull and brief protection · RETRY starts a fresh run with the same setup.':'RETRY starts a fresh run with the same frame, difficulty, sector and contract.';hideAll('gameOverScreen');show('gameOverScreen');hud.classList.add('hidden');renderMenu();
