function transformPoints(points,x,y,angle=0,scale=1){const c=Math.cos(angle),sn=Math.sin(angle);return points.map(([px,py])=>new Phaser.Geom.Point(x+(px*c-py*sn)*scale,y+(px*sn+py*c)*scale))}
function poly(g,pts,color,alpha=1,lineColor=0,lineAlpha=0,lineWidth=0){g.fillStyle(typeof color==='string'?hexColor(color):color,alpha);g.fillPoints(pts,true);if(lineWidth){g.lineStyle(lineWidth,typeof lineColor==='string'?hexColor(lineColor):lineColor,lineAlpha||1);g.strokePoints(pts,true,true)}}
function line(g,x1,y1,x2,y2,color='#ffffff',alpha=1,width=1){g.lineStyle(width,hexColor(color),alpha);g.beginPath();g.moveTo(x1,y1);g.lineTo(x2,y2);g.strokePath()}
function circle(g,x,y,r,color='#ffffff',alpha=1){g.fillStyle(hexColor(color),alpha);g.fillCircle(x,y,r)}
function ring(g,x,y,r,color='#ffffff',alpha=1,width=1){g.lineStyle(width,hexColor(color),alpha);g.strokeCircle(x,y,r)}
function rect(g,x,y,w,h,color='#ffffff',alpha=1){g.fillStyle(hexColor(color),alpha);g.fillRect(x,y,w,h)}
function diamond(g,x,y,r,color='#ffffff',alpha=1){poly(g,[new Phaser.Geom.Point(x,y-r),new Phaser.Geom.Point(x+r,y),new Phaser.Geom.Point(x,y+r),new Phaser.Geom.Point(x-r,y)],color,alpha)}

