function desiredBackground(){
  if(!state||state.mode!=='run')return'deep';if(state.enemies.some(e=>e.boss&&!e.dead))return'supernova';
  const sequence=['deep','pulsar','rift','eclipse','graveyard','supernova'];return sequence[Math.floor(state.time/82)%sequence.length];
}
function drawCelestialAnimation(kind,time){
  if(!celestialG)return;celestialG.clear();celestialG.setBlendMode(Phaser.BlendModes.NORMAL);const t=time*.001;
  if(kind==='supernova'){
    const x=RENDER_W*.925,y=RENDER_H*.46,pulse=.70+.30*Math.sin(t*2.25),wave=(t*56)%(RENDER_W*.28);
    celestialG.fillStyle(0x8d7773,.026+.014*pulse).fillCircle(x,y,92+16*pulse);celestialG.fillStyle(0xc5c7c2,.018+.010*pulse).fillCircle(x,y,58+9*pulse);
    celestialG.lineStyle(4,0xa48278,.08*(1-wave/(RENDER_W*.28))).strokeCircle(x,y,64+wave);celestialG.lineStyle(2,0xc4c9c6,.06*(1-wave/(RENDER_W*.28))).strokeCircle(x,y,82+wave*1.18);
  }else if(kind==='rift'){
    const x=RENDER_W*.15,y=RENDER_H*.43;for(let i=0;i<5;i++){const wobble=Math.sin(t*1.1+i)*7;celestialG.lineStyle(2+i*.45,i%2?0x716d70:0xa7adaa,.032+i*.011).strokeEllipse(x,y,176+i*25+wobble,118+i*17-wobble*.5)}
    celestialG.fillStyle(0x605c60,.018+.010*Math.sin(t*1.3)).fillCircle(x,y,105);
  }else if(kind==='pulsar'){
    const x=RENDER_W*.50,y=RENDER_H*.075,a=.025+.018*(.5+.5*Math.sin(t*2.4));celestialG.fillStyle(0xd5d7d1,.13).fillCircle(x,y,5+Math.sin(t*2.5)*1.2);
    celestialG.lineStyle(3,0xaeb5b1,a).beginPath().moveTo(x,y).lineTo(RENDER_W*.08,RENDER_H*.57).strokePath();celestialG.lineStyle(3,0xaeb5b1,a).beginPath().moveTo(x,y).lineTo(RENDER_W*.92,RENDER_H*.57).strokePath();
  }else if(kind==='eclipse'){
    const x=RENDER_W*.82,y=RENDER_H*.24,pulse=.5+.5*Math.sin(t*.72);celestialG.fillStyle(0x010205,.94).fillCircle(x,y,76);celestialG.lineStyle(6,0x5b60b7,.08+pulse*.025).strokeCircle(x,y,80+pulse*3);celestialG.lineStyle(2,0x55dbe3,.10).strokeCircle(x,y,88+pulse*6);
  }else if(kind==='graveyard'){
    for(let i=0;i<7;i++){const x=(i*241+t*7)%(RENDER_W+260)-130,y=RENDER_H*(.18+(i%4)*.19),s=20+(i%3)*11;celestialG.lineStyle(3,i%2?0x60757f:0x66566f,.07).beginPath().moveTo(x-s,y+s*.35).lineTo(x+s,y-s*.2).lineTo(x+s*.3,y+s*.45).strokePath();celestialG.lineStyle(1,0x52c4cf,.045).strokeCircle(x,y,s*.7)}
  }
}
function updateDynamicBackground(time,delta){
  if(!spaceBg||!spaceBgNext||!backgroundDirector)return;const desired=desiredBackground(),fractureScale=state?.timeFractureRemaining>0?.28:1,visualTime=state?.mode==='run'?(state.time*1000):time,scaledDelta=delta*fractureScale;
  if(desired!==backgroundDirector.current&&desired!==backgroundDirector.target){backgroundDirector.target=desired;backgroundDirector.mix=0;spaceBgNext.setTexture(`space-${desired}`).setAlpha(0)}
  const base=save.settings.graphics==='LOW'?.38:save.settings.graphics==='ULTRA'?.64:.56;
  if(backgroundDirector.target!==backgroundDirector.current){backgroundDirector.mix=clamp(backgroundDirector.mix+scaledDelta/4200,0,1);const x=backgroundDirector.mix,ease=x*x*(3-2*x);spaceBg.setAlpha(base*(1-ease));spaceBgNext.setAlpha(base*ease);if(x>=1){const old=spaceBg;spaceBg=spaceBgNext;spaceBgNext=old;backgroundDirector.current=backgroundDirector.target;spaceBgNext.setAlpha(0)}}else{spaceBg.setAlpha(base);spaceBgNext.setAlpha(0)}
  const dt=clamp(scaledDelta/1000,.001,.05),worldX=state?.worldX||0,worldY=state?.worldY||0,run=state?.mode==='run',motion=save.settings.motion==='REDUCED'?.28:1,moving=!!(run&&state.p.moving),dash=run?clamp((state.p.dashFx||0)/.32,0,1):0;
  const targetPx=run?(Math.sin(worldX*.0022)*22+(state.p.x-W/2)*-.045-(state.p._lastMoveX||0)*(moving?13:0)*motion)*RENDER_SCALE:Math.sin(visualTime*.00008)*10,targetPy=run?(Math.sin(worldY*.0020)*16+(state.p.y-H/2)*-.035-(state.p._lastMoveY||0)*(moving?10:0)*motion)*RENDER_SCALE:Math.cos(visualTime*.00006)*7,targetZoom=1.105+Math.sin(visualTime*.00012)*.008+(moving?.009:0)+dash*.018+(run&&state.rush>0?.004:0);
  backgroundDirector.px=dampValue(backgroundDirector.px||0,targetPx,2.8,dt);backgroundDirector.py=dampValue(backgroundDirector.py||0,targetPy,2.8,dt);backgroundDirector.zoom=dampValue(backgroundDirector.zoom||1.105,targetZoom,3.2,dt);const px=backgroundDirector.px,py=backgroundDirector.py,zoom=backgroundDirector.zoom;
  spaceBg.setPosition(RENDER_W/2+px,RENDER_H/2+py).setDisplaySize(RENDER_W*zoom,RENDER_H*zoom);spaceBgNext.setPosition(RENDER_W/2-px*.55,RENDER_H/2-py*.55).setDisplaySize(RENDER_W*(zoom+.012),RENDER_H*(zoom+.012));
  drawCelestialAnimation(backgroundDirector.target,visualTime);
}
function engineTick(time,delta){pollGamepadPause();pollGamepadUi();if(state){const dt=Math.min(.033,delta/1000);state.last=performance.now();update(dt)}updateDynamicBackground(time,delta);draw()}
