      const usePhaserFallback=()=>{canvas.dataset.engine='phaser-3.90-fallback';canvas.dataset.renderer=this.game.renderer.type===Phaser.WEBGL?'webgl':'canvas';canvas.dataset.renderPipeline=this.game.renderer.type===Phaser.WEBGL?'cinematic-webgl-fallback':'clarity-canvas-v1'};
      usePhaserFallback();const threeReady=globalThis.OrbitThreeEngineReady;if(threeReady?.then)threeReady.then(module=>{const layer=$('gameThree');visualEngine?.destroy?.();visualEngine=new module.OrbitThreeVisualEngine(layer,{width:W,height:H,scale:RENDER_SCALE});layer.classList.add('ready');canvas.dataset.engine='three-r185-topdown';canvas.dataset.renderer='three-webgl';canvas.dataset.visualEngine='three-sprite-material-pools';canvas.dataset.renderPipeline='aces-topdown-v3-depth-graded'}).catch(error=>{console.warn('Three.js presentation layer unavailable; using Phaser fallback.',error);usePhaserFallback()}).finally(finishBoot);else finishBoot()
